from dataclasses import dataclass

@dataclass
class Student:
    name: str
    age: int
    score: float

class StudentRoster:
    def __init__(self):
        self._students = []

    def add(self, name: str, age: int, score: float) -> None:
        self._students.append(Student(name=name, age=age, score=score))

    def average_score(self) -> float:
        if not self._students:
            return 0.0
        return sum(s.score for s in self._students) / len(self._students)

    def top_students(self, n: int):
        sorted_students = sorted(self._students, key=lambda s: s.score, reverse=True)
        return [(s.name, s.age, s.score) for s in sorted_students[:n]]
